test "deberta required tensors match exported names" {
    const allocator = std.testing.allocator;
    var names = std.StringHashMapUnmanaged(void){};
    defer {
        var it = names.iterator();
        while (it.next()) |entry| allocator.free(entry.key_ptr.*);
        names.deinit(allocator);
    }
    var missing = std.ArrayListUnmanaged([]const u8).empty;
    defer {
        for (missing.items) |name| allocator.free(name);
        missing.deinit(allocator);
    }

    const required = [_][]const u8{
        "embeddings.word_embeddings.weight",
        "embeddings.LayerNorm.weight",
        "embeddings.LayerNorm.bias",
        "encoder.rel_embeddings.weight",
        "encoder.LayerNorm.weight",
        "encoder.LayerNorm.bias",
        "encoder.layer.0.attention.self.query_proj.weight",
        "encoder.layer.0.attention.self.query_proj.bias",
        "encoder.layer.0.attention.self.key_proj.weight",
        "encoder.layer.0.attention.self.key_proj.bias",
        "encoder.layer.0.attention.self.value_proj.weight",
        "encoder.layer.0.attention.self.value_proj.bias",
        "encoder.layer.0.attention.output.dense.weight",
        "encoder.layer.0.attention.output.dense.bias",
        "encoder.layer.0.attention.output.LayerNorm.weight",
        "encoder.layer.0.attention.output.LayerNorm.bias",
        "encoder.layer.0.intermediate.dense.weight",
        "encoder.layer.0.intermediate.dense.bias",
        "encoder.layer.0.output.dense.weight",
        "encoder.layer.0.output.dense.bias",
        "encoder.layer.0.output.LayerNorm.weight",
        "encoder.layer.0.output.LayerNorm.bias",
    };
    for (required) |name| {
        try names.put(allocator, try allocator.dupe(u8, name), {});
    }

    try collectMissingRequiredDebertaWeights(allocator, .{
        .hidden_size = 4,
        .num_hidden_layers = 1,
        .num_attention_heads = 2,
        .intermediate_size = 8,
    }, &names, &missing);
    try std.testing.expectEqual(@as(usize, 0), missing.items.len);
}

test "ModernBERT GGUF inventory requires the fused encoder graph" {
    const allocator = std.testing.allocator;
    var names = std.StringHashMapUnmanaged(void){};
    defer {
        var it = names.iterator();
        while (it.next()) |entry| allocator.free(entry.key_ptr.*);
        names.deinit(allocator);
    }
    const required = [_][]const u8{
        "model.embeddings.tok_embeddings.weight",
        "model.embeddings.norm.weight",
        "model.final_norm.weight",
        "model.layers.0.attn.Wqkv.weight",
        "model.layers.0.attn.Wo.weight",
        "model.layers.0.mlp_norm.weight",
        "model.layers.0.mlp.Wi.weight",
        "model.layers.0.mlp.Wo.weight",
    };
    for (required) |name| try names.put(allocator, try allocator.dupe(u8, name), {});

    var missing = std.ArrayListUnmanaged([]const u8).empty;
    defer {
        for (missing.items) |name| allocator.free(name);
        missing.deinit(allocator);
    }
    const config = modern_bert_arch.Config{
        .num_hidden_layers = 1,
        .checkpoint_layout = .huggingface_fused_qkv_no_bias,
    };
    try collectMissingRequiredModernBertWeights(allocator, config, &names, &missing);
    try std.testing.expectEqual(@as(usize, 0), missing.items.len);

    const removed = names.fetchRemove("model.layers.0.attn.Wqkv.weight") orelse return error.TestUnexpectedResult;
    allocator.free(removed.key);
    try collectMissingRequiredModernBertWeights(allocator, config, &names, &missing);
    try std.testing.expectEqual(@as(usize, 1), missing.items.len);
    try std.testing.expectEqualStrings("model.layers.0.attn.Wqkv.weight", missing.items[0]);
}

test "declared GLiNER ModernBERT GGUF inventory also requires its classifier" {
    const allocator = std.testing.allocator;
    var names = std.StringHashMapUnmanaged(void){};
    defer {
        var it = names.iterator();
        while (it.next()) |entry| allocator.free(entry.key_ptr.*);
        names.deinit(allocator);
    }
    inline for (&.{
        "classifier.0.weight",
        "classifier.0.bias",
        "classifier.2.weight",
        "classifier.2.bias",
    }) |name| try names.put(allocator, try allocator.dupe(u8, name), {});

    var missing = std.ArrayListUnmanaged([]const u8).empty;
    defer {
        for (missing.items) |name| allocator.free(name);
        missing.deinit(allocator);
    }

    // Generic ModernBERT only asks for encoder tensors. The composite GLiNER
    // wrapper opts into this additional inventory explicitly.
    try collectMissingRequiredGlinerModernBertClassifier(allocator, &names, &missing);
    try std.testing.expectEqual(@as(usize, 0), missing.items.len);

    const removed = names.fetchRemove("classifier.2.bias") orelse return error.TestUnexpectedResult;
    allocator.free(removed.key);
    try collectMissingRequiredGlinerModernBertClassifier(allocator, &names, &missing);
    try std.testing.expectEqual(@as(usize, 1), missing.items.len);
    try std.testing.expectEqualStrings("classifier.2.bias", missing.items[0]);
}

test "gliner base weight key preserves exported gguf deberta names" {
    try std.testing.expectEqualStrings("embeddings.word_embeddings.weight", glinerBaseWeightKey("encoder.embeddings.word_embeddings.weight"));
    try std.testing.expectEqualStrings("encoder.rel_embeddings.weight", glinerBaseWeightKey("encoder.rel_embeddings.weight"));
    try std.testing.expectEqualStrings("encoder.rel_embeddings.weight", glinerBaseWeightKey("encoder.encoder.rel_embeddings.weight"));
    try std.testing.expectEqualStrings("span_rep.weight", glinerBaseWeightKey("span_rep.weight"));
}

// --- Unified Session implementation ---

const native_mod = @import("../ops/native_compute.zig");
const gpu_hosted_store_mod = @import("../ops/gpu_hosted_store.zig");
const NativeData = native_mod.WeightStore;
const LazyWeightEntry = native_mod.LazyWeightEntry;

const GpuHostedData = if (false or build_options.enable_metal) gpu_hosted_store_mod.WeightStore else void;

/// PJRT backend data: weights are stored and served via the native backend,
/// while the PJRT client is used for compiled partition execution.
const PjrtData = struct {
    /// Native weight store — PJRT uses the native backend for data
    /// conversion (host CTs ↔ PJRT buffers).
    native: NativeData,
    /// Initialized PJRT client. null when the plugin was not found and we
    /// fell back to pure native CPU execution.
    client: if (build_options.enable_pjrt) ?pjrt_lib.pjrt.Client else void =
        if (build_options.enable_pjrt) null else {},
};

const CudaData = struct {
    compute: if (build_options.enable_cuda) *cuda_compute_mod.CudaCompute else void,
};

const BackendData = union {
    native: NativeData,
    metal: if (build_options.enable_metal) GpuHostedData else void,
    cuda: if (build_options.enable_cuda) CudaData else void,
    pjrt: PjrtData,
};

const ArchSession = struct {
    diagnostics: @import("diagnostics.zig").Diagnostics = .{},
    model_lifetime: Session.ModelLifetime = .{ .owner = undefined, .destroy_fn = archClose, .destroy_with_boundary_fn = archCloseWithBoundary, .quiesce_fn = archQuiesce },
    // Independent of the model execution lane: preparation can overlap model
    // work. Session close follows worker shutdown, like the borrowed device.
    video_coefficient_mutex: std.Io.Mutex = .init,
    video_coefficients: ?@import("antfly_video").preparation.CoefficientCache = null,
    video_coefficient_permit: ?@import("../backends/session.zig").RunPermit = null,
    video_coefficient_device_permit: ?@import("../backends/session.zig").RunPermit = null,
    video_coefficient_suspended: bool = false,
    allocator: std.mem.Allocator,
    arch_config: ArchConfig,
    recurrent_execution: ?qwen35_execution.Decision = null,
    boundary_identity: ?boundary_bundle.Identity = null,
    gliner_decision_identity: ?gliner_decide_qualification.Identity = null,
    gliner_decision_identity_sealed: bool = false,
    task: SessionTask = .generic,
    /// A ModernBERT extractor is a GLiNER span session only when its manifest
    /// declared the SpanExtractor wrapper and nested ModernBERT encoder.
    gliner_span_encoder_family: manifest_mod.GlinerSpanEncoderFamily = .unknown,
    /// Only real DeBERTa reranker sessions may trade persistent mirror memory
    /// for the resident fused-layer path. Generic classifiers stay unchanged.
    deberta_reranker_weight_mirrors: bool = false,
    backend_type: BackendType,
    kernel_jit_config: kernel_jit.Config = .{},
    kernel_jit_load_context: kernel_jit.LoadContext = .dynamic,
    metal_jit_scope: MetalJitRouteScope = if (build_options.enable_metal)
        metal_runtime.MetalJitRouteScope.none()
    else {},
    budget_floor: runtime.tier.memory.Limits = .{},
    generation_workspace: ?runtime.tier.memory.ReservedGenerationWorkspace = null,
    shared_cache_budget_floor: runtime.tier.cache.Budget = .{},
    backend_data: BackendData,
    /// Optional Io for parallel GEMM dispatch via lib/linalg's Io variants.
    /// Set by `attachIo` (called from SessionManager when its `io` field is
    /// non-null).  Threaded through `makeComputeBackend` to NativeCompute
    /// /GpuHostedCompute/MetalCompute via their `initWithIo` constructors.
    io: ?std.Io = null,
    /// Optional graph-runtime execution strategy.  Set by
    /// `attachGraphRuntimeStrategy` (called from SessionManager when its
    /// `graph_runtime_strategy` field is non-null).  The eager `runArch`
    /// path consults this on a per-architecture basis: today only the
    /// gliner branch routes through `gliner_head_graph.forwardViaGraph`
    /// when this is set; other architectures fall through to their
    /// existing eager path.
    graph_runtime_strategy: ?graph_runtime.Strategy = null,
    /// Tree-packed Laya trunk keys and values, created on first packed run.
    laya_trunk_cache: ?*@import("../architectures/laya_trunk_cache.zig").Cache = null,
    laya_trunk_cache_lock: std.atomic.Mutex = .unlocked,
    whisper_definitions: @import("dense_decoder_schedule.zig").DefinitionSlot = .{},
    whisper_definition_retirement_mutex: std.atomic.Mutex = .unlocked,
    retired_whisper_definitions: ?*@import("dense_decoder_schedule.zig").Definition = null,
};

const GlinerDecisionIdentityHandoff = struct {
    identity: ?gliner_decide_qualification.Identity,
    sealed: bool,
};

/// Backend conversion preserves the exact artifact identity captured by the
/// source loader, but the published session must be sealed independently only
/// after ModelManager parses and verifies its tokenizer snapshot. An already
/// sealed source therefore never transfers sealing authority to a new owner.
fn unsealedGlinerDecisionIdentityHandoff(identity: ?gliner_decide_qualification.Identity) GlinerDecisionIdentityHandoff {
    return .{ .identity = identity, .sealed = false };
}

fn layaTrunkCache(self: *ArchSession) ?*@import("../architectures/laya_trunk_cache.zig").Cache {
    platform.sync.lockYielding(&self.laya_trunk_cache_lock);
    defer self.laya_trunk_cache_lock.unlock();
    if (self.laya_trunk_cache == null) {
        const cache = self.allocator.create(@import("../architectures/laya_trunk_cache.zig").Cache) catch return null;
        cache.* = @import("../architectures/laya_trunk_cache.zig").Cache.fromEnvironment(self.allocator);
        self.laya_trunk_cache = cache;
    }
    return self.laya_trunk_cache;
}

/// Hit/miss counters of a packed Laya session's trunk cache.
pub fn layaTrunkCacheStats(session: Session) ?@import("../architectures/laya_trunk_cache.zig").Stats {
    if (session.vtable != &arch_vtable) return null;
    const self: *ArchSession = @ptrCast(@alignCast(session.ptr));
    const cache = layaTrunkCache(self) orelse return null;
    return cache.snapshot();
}

/// Choose f16 (default) or exact f32 entries for new trunk cache entries.
pub fn setLayaTrunkCachePrecision(session: Session, precision: @import("../architectures/laya_trunk_cache.zig").Precision) void {
    if (session.vtable != &arch_vtable) return;
    const self: *ArchSession = @ptrCast(@alignCast(session.ptr));
    const cache = layaTrunkCache(self) orelse return;
    cache.setPrecision(precision);
}

/// Replace a session's trunk cache budget (0 disables it) and minimum
/// cached trunk length.
pub fn setLayaTrunkCacheLimit(session: Session, limit_bytes: usize, min_tokens: usize) void {
    if (session.vtable != &arch_vtable) return;
    const self: *ArchSession = @ptrCast(@alignCast(session.ptr));
    const cache = layaTrunkCache(self) orelse return;
    cache.setLimit(limit_bytes, min_tokens);
}

/// Attach a runtime Io to a Session created by this factory so its
/// compute backend dispatches matmul work through the caller's thread
/// pool.  Safe to call on any Session; no-op when the Session wasn't
/// produced by `createNativeSession` / `createMetalSession`.
pub fn attachIo(session: Session, io: std.Io) void {
    if (session.vtable != &arch_vtable) return;
    const arch_session: *ArchSession = @ptrCast(@alignCast(session.ptr));
    arch_session.io = io;
}

/// Attach a graph-runtime execution strategy to a Session created by this
/// factory.  Mirrors `attachIo`'s lifecycle: SessionManager calls it after
/// `loadFromDir` if its own `graph_runtime_strategy` is non-null.  Today
/// only the gliner branch consults the field (routing through the
/// CT-resident graph path when non-null); other architectures fall
/// through to their existing eager forward.  No-op when called on a
/// Session this factory didn't produce.
pub fn attachGraphRuntimeStrategy(session: Session, strategy: graph_runtime.Strategy) void {
    if (session.vtable != &arch_vtable) return;
    const arch_session: *ArchSession = @ptrCast(@alignCast(session.ptr));
    arch_session.graph_runtime_strategy = strategy;
}

pub const MetalWorkloadProfileExport = if (build_options.enable_metal) metal_runtime.WorkloadProfileExport else void;

/// Full published provider descriptor BEFORE its concrete ctx cast. A forwarded
/// Session may keep that same provider/model owner; a copied/custom table or
/// unrelated Model pin cannot certify the actual SDK endpoint.
/// Lane order follows the ACTUAL model capability, independent of optional
/// public decoder metadata or batching flags. null is an unknown raw provider;
/// a known non-Qwen model returns false and cannot be relabelled by metadata.
pub fn qwenWorkspaceLanePolicy(session: Session) ?bool {
    const owner: *const ArchSession = actual: {
        if (session.compute_backend_provider) |provider| {
            if (session.model_lifetime) |model| {
                if (provider.services == &archComputeServices and model.owner == provider.ptr)
                    break :actual @ptrCast(@alignCast(provider.ptr));
            }
        }
        if (session.vtable != &arch_vtable) return null;
        break :actual @ptrCast(@alignCast(session.ptr)); // exact original table before cast
    };
    if (owner.backend_type != .metal) return false;
    return switch (owner.arch_config) {
        .gpt => |cfg| gpt_arch.denseQwen3PrefillEligible(cfg),
        else => false,
    };
}

/// Lane order is an immutable ACTUAL model fact, including value-copy
/// forwarding headers retaining the original published provider/Model owner.
fn publishedArchitectureOwner(session: Session) ?*const ArchSession {
    const owner: *const ArchSession = actual: {
        if (session.compute_backend_provider) |provider| {
            if (session.model_lifetime) |model| {
                if (provider.services == &archComputeServices and model.owner == provider.ptr and
                    model.destroy_fn == archClose and model.quiesce_fn == archQuiesce)
                {
                    const actual: *const ArchSession = @ptrCast(@alignCast(provider.ptr));
                    if (&actual.model_lifetime != model) return null;
                    break :actual actual;
                }
            }
        }
        if (session.vtable != &arch_vtable) return null;
        if (session.model_lifetime) |model| {
            if (model.destroy_fn != archClose or model.quiesce_fn != archQuiesce or model.owner != session.ptr) return null;
        }
        break :actual @ptrCast(@alignCast(session.ptr));
    };
    if (session.model_lifetime) |model| if (&owner.model_lifetime != model) return null;
    return owner;
}

pub fn gemmaWorkspaceLanePolicy(session: Session) ?bool {
    const owner = publishedArchitectureOwner(session) orelse return null;
    return owner.arch_config == .embedding_gemma2;
}

/// Immutable actual-model backend, retaining forwarded provider authority.
/// No public callback or transient wrapper implementation is dereferenced.
/// This is metadata only; it never certifies a public output callback.
pub fn publishedModelBackend(session: Session) ?BackendType {
    // Full endpoint identity precedes opaque Model access. Forwarders retain
    // the original typed provider; a copied public table alone grants nothing.
    const original_provider = if (session.compute_backend_provider) |provider| provider.services == &archComputeServices else false;
    if (session.vtable != &arch_vtable and !original_provider) return null;
    const model = session.model_lifetime orelse return null;
    if (model.destroy_fn != archClose or model.quiesce_fn != archQuiesce) return null;
    // The canonical public table will dispatch with THIS receiver. A valid
    // provider may forward metadata for a custom wrapper, but cannot repair
    // an unrelated receiver paired with our own direct callbacks.
    if (session.vtable == &arch_vtable and model.owner != session.ptr) return null;
    const owner = publishedArchitectureOwner(session) orelse return null;
    return owner.backend_type;
}

/// Reject inconsistent headers only for this owner's recognized endpoint or
/// typed provider. Unknown custom/imported owners retain their own contract;
/// a null architecture query must not turn a known invalid owner into one.
pub fn hasInvalidPublishedModelHeader(session: Session) bool {
    const original_provider = if (session.compute_backend_provider) |provider| provider.services == &archComputeServices else false;
    if (session.vtable != &arch_vtable and !original_provider) return false;
    return publishedModelBackend(session) == null;
}

/// Exact resident callback/config geometry for the generic public CUDA text
/// entry. Forwarded/custom host callbacks retain their original raw contract;
/// a provider/config hint alone cannot authorize an owned result envelope.
pub fn gemmaCudaOwnedTextWidth(session: Session) ?usize {
    if (session.vtable != &arch_vtable) return null;
    const model = session.model_lifetime orelse return null;
    if (model.destroy_fn != archClose or model.quiesce_fn != archQuiesce or model.owner != session.ptr) return null;
    const provider = session.compute_backend_provider orelse return null;
    if (provider.ptr != session.ptr or provider.services != &archComputeServices) return null;
    const actual: *const ArchSession = @ptrCast(@alignCast(session.ptr));
    if (&actual.model_lifetime != model) return null;
    if (actual.backend_type != .cuda or actual.arch_config != .embedding_gemma2 or actual.task == .classifier or actual.task == .extractor) return null;
    const config = actual.arch_config.embedding_gemma2.resident orelse return null;
    config.validate() catch return null;
    if (!config.isOfficialTextTopology()) return null;
    return config.outputDim();
}

/// Source's synchronous weight-operation protocol is independent of encoder
/// names. The exclusions are actual different producer/worker ownership:
/// expert workers, an explicitly installed graph runtime and Gemma's distinct
/// canonical BF16 packed-media caches. Layout selection remains in Native's
/// original per-operation geometry/policy queries.
pub fn nativeWeightPreparationCandidate(session: Session) bool {
    if (comptime !build_options.enable_native) return false;
    if (session.vtable != &arch_vtable) return false;
    const owner: *const ArchSession = @ptrCast(@alignCast(session.ptr));
    if (owner.backend_type != .native or owner.graph_runtime_strategy != null) return false;
    // Do not touch the storage union through a raw/incomplete owner header.
    // The actual published Model/gate identity certifies this additional
    // expert-worker exclusion; missing admitted ownership is rejected below.
    if (session.compute_backend_provider) |provider| if (session.model_lifetime) |model| {
        if (provider.services == &archComputeServices and provider.ptr == session.ptr and model.owner == provider.ptr and model.destroy_fn == archClose and &owner.model_lifetime == model and session.execution_gate == &model.execution_gate) {
            if (owner.backend_data.native.moe_num_experts != 0) return false;
        }
    };
    return switch (owner.arch_config) {
        .embedding_gemma2 => false,
        .gpt => |cfg| cfg.num_local_experts == 0 and cfg.family != .deepseek_v4,
        else => true,
    };
}
/// Actual published owner facts govern raw compatibility. Public wrapper
/// policy removal cannot unbind a Model/cache which still owns admission.
pub fn validateNativePanelPreparationReceiver(session: Session) !void {
    if (comptime !build_options.enable_native) return;
    if (session.vtable != &arch_vtable) return;
    const model = session.model_lifetime orelse return error.MissingNativePanelOwner;
    if (model.owner != session.ptr or model.destroy_fn != archClose) return error.ForeignNativeWeightModel;
    if (session.compute_backend_provider) |provider| if (provider.services != &archComputeServices or provider.ptr != session.ptr) return error.ForeignNativeWeightModel;
    const actual: *ArchSession = @ptrCast(@alignCast(model.owner));
    if (&actual.model_lifetime != model) return error.ForeignNativeWeightModel;
    if (actual.backend_type != .native or actual.arch_config != .embedding_gemma2) return;
    const cache_binding = if (actual.backend_data.native.tier_cache) |*cache| cache.admission else null;
    const raw = session.run_admission == null and model.model_lease == null and model.resource_pin == null and model.admission_domain == null and cache_binding == null;
    if (raw) return;
    const policy = session.run_admission orelse return error.MissingNativePanelAdmission;
    const domain = model.admission_domain orelse return error.MissingCacheRetirementDomain;
    if (policy.controller != domain.controller() or policy.backend_class != .cpu) return error.ForeignAdmissionDomain;
    if (cache_binding) |binding| if (binding.controller != policy.controller or binding.backend_class != policy.backend_class) return error.ForeignAdmissionDomain;
    if (session.execution_gate != &model.execution_gate) return error.ExecutionCohortGateChanged;
}

pub fn nativePanelPreparationModelData(session: Session) ?*native_mod.WeightStore {
    if (comptime !build_options.enable_native) return null;
    if (session.vtable != &arch_vtable or session.run_admission == null) return null;
    const provider = session.compute_backend_provider orelse return null;
    const model = session.model_lifetime orelse return null;
    if (provider.services != &archComputeServices or provider.ptr != session.ptr or model.owner != provider.ptr or model.destroy_fn != archClose or session.execution_gate != &model.execution_gate) return null;
    const owner: *ArchSession = @ptrCast(@alignCast(provider.ptr));
    if (&owner.model_lifetime != model or owner.backend_type != .native or owner.arch_config != .embedding_gemma2 or owner.graph_runtime_strategy != null) return null;
    const domain = model.admission_domain orelse return null;
    if (domain.controller() != session.run_admission.?.controller) return null;
    return &owner.backend_data.native;
}

/// Exact published owner/gate certification before the Native ctx is exposed.
/// Neither copied callback tables nor public model strings prove this identity.
pub fn nativeWeightPreparationModelData(session: Session) ?*native_mod.WeightStore {
    if (!nativeWeightPreparationCandidate(session)) return null;
    const provider = session.compute_backend_provider orelse return null;
    const model = session.model_lifetime orelse return null;
    if (provider.services != &archComputeServices or provider.ptr != session.ptr or model.owner != provider.ptr or model.destroy_fn != archClose or session.execution_gate != &model.execution_gate) return null;
    const owner: *ArchSession = @ptrCast(@alignCast(provider.ptr));
    if (&owner.model_lifetime != model) return null;
    return &owner.backend_data.native;
}
/// Bounded actual unpacked adapter. The generic backend receives only an
/// explicit reusable span; model roles remain in the checkpoint inventory.
pub fn nativeMatrixScratchCandidate(session: Session, inputs: @import("prepared_invocation.zig").Inputs) !?ops.kernel_descriptor.NativeMatrixScratchGeometry {
    if (nativeWeightPreparationModelData(session) == null or session.run_admission == null) return null;
    const policy = session.run_admission.?;
    const model = session.model_lifetime.?; // canonical model proof above
    const domain = model.retainAdmissionDomain(policy.controller) orelse return null;
    defer domain.release();
    const owner: *const ArchSession = @ptrCast(@alignCast(session.ptr));
    if (owner.arch_config != .modern_bert) return null;
    const cfg = owner.arch_config.modern_bert;
    const laya = cfg.laya orelse return null;
    const host = switch (inputs) {
        .host => |values| values,
        else => return null,
    };
    if (host.len == @import("../architectures/laya_packed.zig").input_count and laya.packing.enabled()) {
        const row = @import("../architectures/laya_packed.zig").metadataView(cfg, host) catch return null;
        // Full and cached branch callers both have positive encoder rows and
        // head questions. A hot trunk has zero new FILL rows, not zero branch
        // math; all selected serial phases reuse this SAME MAX span.
        if (row.ids.len == 0 or row.questions() == 0) return null;
        return @import("../models/laya.zig").selectedMatrixScratchGeometry(laya, cfg, .{ .encoder = true, .head = true });
    }
    if (host.len != 4 or host[0].shape.len != 2 or host[0].shape[0] <= 0 or host[0].shape[1] <= 0) return null;
    const bi = parseBertRunInputs(host[0..2]) catch return null;
    const kinds = validateI64Matrix(host[2], .{ bi.batch, 1 }) catch return null;
    const markers = validateI64Matrix(host[3], null) catch return null;
    if (markers.shape[0] != bi.batch or markers.shape[1] < 2 or markers.shape[1] > 20) return null;
    for (bi.input_ids) |id| if (id < 0 or id >= cfg.vocab_size) return null;
    for (kinds.values) |kind| if (kind < 0 or kind > 2) return null;
    for (0..bi.batch) |row| {
        var valid: usize = 0;
        for (markers.values[row * markers.shape[1] ..][0..markers.shape[1]]) |marker| {
            if (marker == -1) continue;
            if (marker < 0 or marker >= bi.seq_len or bi.attention_mask[row * bi.seq_len + @as(usize, @intCast(marker))] != 1) return null;
            valid += 1;
        }
        if (valid < 2) return null;
    }
    // Four actual inputs select the original unpacked numerical branch. Packed
    // trunk/cache selection requires its own positive-work proof and declines.
    return @import("../models/laya.zig").unpackedMatrixScratchGeometry(laya, cfg, @intCast(host[0].shape[0]), @intCast(host[0].shape[1]));
}

/// Metadata-only actual layout census. Caller owns the selected real Model
/// gate; no allocation, supplier, codec or numerical dispatch occurs here.
pub fn nativeMatrixScratchGeometry(session: Session, inputs: @import("prepared_invocation.zig").Inputs) !?ops.kernel_descriptor.NativeMatrixScratchGeometry {
    const geometry = (try nativeMatrixScratchCandidate(session, inputs)) orelse return null;
    return if (try nativeMatrixScratchMatches(session, geometry)) geometry else null;
}
pub fn nativeMatrixScratchMatches(session: Session, geometry: ops.kernel_descriptor.NativeMatrixScratchGeometry) !bool {
    const data = nativeWeightPreparationModelData(session) orelse return false;
    const owner: *ArchSession = @ptrCast(@alignCast(session.ptr));
    if (owner.arch_config != .modern_bert) return false;
    const cfg = owner.arch_config.modern_bert;
    const laya = cfg.laya orelse return false;
    // Matrix demand is row independent; positive execution was established
    // from actual input shapes before the bank was declared.
    const current = (try if (laya.packing.enabled())
        @import("../models/laya.zig").selectedMatrixScratchGeometry(laya, cfg, .{ .encoder = true, .head = true })
    else
        @import("../models/laya.zig").unpackedMatrixScratchGeometry(laya, cfg, 1, 1)) orelse return false;
    if (!std.meta.eql(current, geometry)) return false;
    const Census = struct {
        owner: *ArchSession,
        data: *native_mod.WeightStore,
        supported: bool = true,
        pub fn tensor(self: *@This(), name: []const u8, shape: []const i64) !void {
            if (!@import("../models/laya.zig").quantizedLinear(name)) return;
            var name_buf: [256]u8 = undefined;
            const key = try normalizeWeightKey(.safetensors, self.owner.arch_config, name, &name_buf);
            const loaded = self.data.resident_weights.getPtr(key) orelse {
                self.supported = false; // lazy/raw/unknown retained source is not this bank
                return;
            };
            const storage = if (loaded.quantized_storage) |*value| value else {
                self.supported = false;
                return;
            };
            if (storage.tensor_type != .known or storage.tensor_type.known != .Q8_0 or !std.mem.eql(i64, shape, storage.shape)) self.supported = false;
        }
    };
    if (data.prefetch_initialized) data.prefetch.lock();
    defer if (data.prefetch_initialized) data.prefetch.unlock();
    @import("antfly_platform").sync.lockYielding(&data.quantized_prepare_lock);
    defer data.quantized_prepare_lock.unlock();
    var census = Census{ .owner = owner, .data = data };
    try @import("../models/laya.zig").visitTensorInventory(&census, laya, cfg);
    return census.supported;
}

/// Model interpretation remains in this registered adapter. Generic Source
/// sees the same cold-work object/requirements and original permit ownership;
/// no Laya geometry/layout type is introduced into Native backend APIs.
pub const NativeMatrixScratchReceiver = @import("../architectures/laya_packed.zig").Prepared;
pub const NativeMatrixScratchCall = struct {
    owner: *ArchSession,
    workload: ?@import("../architectures/laya_packed.zig").ColdCall,
    expected_geometry: ?ops.kernel_descriptor.NativeMatrixScratchGeometry = null,
    pub fn declineAdditionalWorkspace(self: *@This()) !void {
        if (self.workload) |*call| try call.declineAdditionalWorkspace();
    }
    pub fn physicalRequirements(self: *const @This()) []const @import("prepared_storage_admission.zig").Requirement {
        return if (self.workload) |*call| call.physicalRequirements() else &.{};
    }
    pub fn ownedAmounts(self: *@This(), controller: *runtime.tier.memory.AdmissionController) !runtime.tier.memory.AdmissionAmounts {
        return if (self.workload) |*call| try call.cache.ownedAmountsCold(&call.snapshot_value, controller) else .{};
    }
    pub fn prepareOutsideExecution(self: *@This(), capability: @import("storage_admission.zig").Capability, domain: @import("../runtime/tier/admission_domain.zig").Pin, current: @import("cleanup_context.zig").Context) !void {
        if (self.workload) |*call| try call.prepareOutsideExecution(capability, domain, current);
    }
    pub fn finishOutsideExecution(self: *@This(), current: @import("cleanup_context.zig").Context) !void {
        if (self.workload) |*call| try call.finishOutsideExecution(current);
        self.workload = null;
    }
    pub fn receiverAtFinalAddress(self: *@This()) !?*@import("../architectures/laya_packed.zig").Prepared {
        return if (self.workload) |*call| try call.receiverAtFinalAddress() else null;
    }
};

pub fn nativePackedSourceInputs(session: Session, inputs: []const Tensor) bool {
    if (inputs.len != @import("../architectures/laya_packed.zig").input_count or nativeWeightPreparationModelData(session) == null) return false;
    const owner: *const ArchSession = @ptrCast(@alignCast(session.ptr));
    return owner.arch_config == .modern_bert and owner.arch_config.modern_bert.laya != null and owner.arch_config.modern_bert.laya.?.packing.enabled();
}
pub fn nativeMatrixScratchCallMatches(session: Session, call: *NativeMatrixScratchCall, geometry: ops.kernel_descriptor.NativeMatrixScratchGeometry) !bool {
    if (session.vtable != &arch_vtable or nativeWeightPreparationModelData(session) == null or session.ptr != @as(*anyopaque, @ptrCast(call.owner))) return false;
    if (!try nativePackedMatrixReady(session, geometry)) return false;
    if (call.workload) |*workload| {
        if (call.owner.laya_trunk_cache != workload.cache or !std.meta.eql(call.owner.arch_config.modern_bert, workload.config)) return false;
        try workload.validateBeforeExecution();
    }
    return true;
}

pub fn prepareNativeMatrixCreditsOutsideExecution(session: Session, domain: *const @import("../runtime/tier/admission_domain.zig").Pin) !void {
    const data = nativeWeightPreparationModelData(session) orelse return error.ForeignNativeWeightModel;
    if (data.tier_cache) |*cache| {
        for (0..8) |_| {
            if (!cache.rawCreditsNeedPreparation()) break;
            var upgrade = cache.prepareCreditUpgradesOutsideExecution(domain) catch |err| {
                if (err == error.PreparedCacheGrowthChanged) continue;
                return err;
            };
            defer upgrade.finishOutsideExecution();
            upgrade.installLocked(cache) catch |err| {
                if (err == error.PreparedCacheGrowthChanged) continue;
                return err;
            };
            break;
        }
        if (cache.rawCreditsNeedPreparation()) return error.ResourceTemporarilyUnavailable;
        try cache.flushReleasedOutsideExecution();
    }
}

/// Caller owns the actual Model metadata gate. Complete resident inventory and
/// the accepted Q8 MAX prove no selected weight operation needs a cold slice
/// while a pending trunk fill owns the numerical Model. Unknown/lazy/scratch
/// variants decline before the original task permit moves.
pub fn nativePackedMatrixReady(session: Session, geometry: ops.kernel_descriptor.NativeMatrixScratchGeometry) !bool {
    if (!try nativeMatrixScratchMatches(session, geometry)) return false;
    const data = nativeWeightPreparationModelData(session) orelse return false;
    const owner: *ArchSession = @ptrCast(@alignCast(session.ptr));
    if (owner.arch_config != .modern_bert) return false;
    const cfg = owner.arch_config.modern_bert;
    const laya = cfg.laya orelse return false;
    if (!laya.packing.enabled()) return false;
    if (data.tier_cache) |*cache| if (cache.rawCreditsNeedPreparation() or cache.releasedCreditPending()) return false;
    const Census = struct {
        owner: *ArchSession,
        data: *native_mod.WeightStore,
        supported: bool = true,
        pub fn tensor(self: *@This(), name: []const u8, shape: []const i64) !void {
            var buffer: [256]u8 = undefined;
            const key = try normalizeWeightKey(.safetensors, self.owner.arch_config, name, &buffer);
            const loaded = self.data.resident_weights.getPtr(key) orelse {
                self.supported = false;
                return;
            };
            const actual = if (loaded.quantized_storage) |*value| value.shape else loaded.tensor.shape;
            if (!std.mem.eql(i64, actual, shape)) self.supported = false;
            if (@import("../models/laya.zig").quantizedLinear(name)) {
                const storage = if (loaded.quantized_storage) |*value| value else {
                    self.supported = false;
                    return;
                };
                if (storage.tensor_type != .known or storage.tensor_type.known != .Q8_0) self.supported = false;
            } else if (loaded.quantized_storage != null or loaded.tensor.dtype != .f32) self.supported = false;
        }
    };
    if (data.prefetch_initialized) data.prefetch.lock();
    defer if (data.prefetch_initialized) data.prefetch.unlock();
    @import("antfly_platform").sync.lockYielding(&data.quantized_prepare_lock);
    defer data.quantized_prepare_lock.unlock();
    var census = Census{ .owner = owner, .data = data };
    try @import("../models/laya.zig").visitTensorInventory(&census, laya, cfg);
    return census.supported;
}

/// No Model/lane/FIFO is held. Actual managed loading has already created and
/// configured this Cache before publication; raw constructor-only sessions keep
/// their original route instead of allocating a cache under numerical Model.
pub fn collectNativeMatrixScratchCallOutsideExecution(session: Session, inputs: []const Tensor, allocator: std.mem.Allocator, current: @import("cleanup_context.zig").Context) !?NativeMatrixScratchCall {
    if (session.vtable != &arch_vtable or nativeWeightPreparationModelData(session) == null) return null;
    const owner: *ArchSession = @ptrCast(@alignCast(session.ptr));
    if (owner.arch_config != .modern_bert) return null;
    const laya = owner.arch_config.modern_bert.laya orelse return null;
    if (!laya.packing.enabled()) return null;
    const cache = owner.laya_trunk_cache orelse return null;
    if (!cache.supportsColdOwnership()) return null;
    // Concrete cold caller already released Model/FIFO/lane. Settle only
    // detached pure owners before new credit; never lend still-live bytes.
    try cache.drainRetiredOutsideExecution(.{ .outside_execution = true });
    return .{ .owner = owner, .workload = try @import("../architectures/laya_packed.zig").ColdCall.collectOutsideExecution(allocator, owner.arch_config.modern_bert, inputs, cache, current) };
}

pub fn validateNativeWeightPreparationReceiver(session: Session) !void {
    if (session.run_admission != null and nativeWeightPreparationCandidate(session) and nativeWeightPreparationModelData(session) == null) return error.MissingNativeWeightPreparationOwner;
}

pub fn acceptsMetalWorkspaceSession(session: Session) bool {
    const provider = session.compute_backend_provider orelse return false;
    const model = session.model_lifetime orelse return false;
    if (provider.services != &archComputeServices or model.owner != provider.ptr) return false;
    const owner: *ArchSession = @ptrCast(@alignCast(provider.ptr));
    return owner.backend_type == .metal;
}
fn acceptsQwenWorkspaceSession(session: Session) bool {
    return session.vtable == &arch_vtable and acceptsMetalWorkspaceSession(session) and
        session.compute_backend_provider.?.ptr == session.ptr;
}

fn qwenWorkspaceProvider(session: Session) !*@import("../backends/metal_native_provider.zig").MetalNativeProvider {
    if (comptime !build_options.enable_metal) return error.UnsupportedBackend;
    if (session.vtable != &arch_vtable) return error.UnsupportedBackend;
    const arch: *ArchSession = @ptrCast(@alignCast(session.ptr));
    if (arch.backend_type != .metal) return error.UnsupportedBackend;
    return gpuBackendData(arch).shared_metal_native_provider orelse error.MissingMetalNativeProvider;
}

/// Actual cold physical census. This synchronous owner retains the existing
/// loaded-model endpoint while copied SDK identities/pure Root pins are used
/// for admission. The model pin itself grants NO physical workspace credit.
pub const MetalWorkspaceCensus = struct {
    target: @import("../backends/cold_compute_target.zig").Retained,
    physical: @import("../backends/metal_workspace_roles.zig").Snapshot,

    pub fn deinitOutsideExecution(self: *MetalWorkspaceCensus) void {
        self.physical.deinitOutsideExecution();
        self.target.deinit();
        self.* = undefined;
    }
};

/// Certified pre-admission caller ONLY: no Model/cohort/outer numerical lane.
/// Every wait remains with that caller's existing finite readiness protocol.
/// This helper is nonblocking, including a null/deadline-free raw caller; it
/// never constructs a compute backend, prepares SDK slots or invokes supplier
/// callbacks while owning the provider metadata exclusion.
pub fn snapshotQwenWorkspaceOutsideExecution(session: Session, control: ?InferenceExecutionControl) !?QwenWorkspaceCensus {
    if (!acceptsQwenWorkspaceSession(session)) return null;
    return snapshotWorkspaceOutsideExecution(session, control, false);
}

/// Generic existing-root census, ZERO storage-credit authority. This fast
/// declines missing/unpublished providers and copied/custom service tables;
/// supported forwarded headers retain the SAME actual Model/provider owner.
/// The returned target is a synchronous pin only. A caller-owned existing-use
/// holder moves out the pure Snapshot and releases target outside all gates.
pub fn snapshotMetalWorkspaceOutsideExecution(session: Session, control: ?InferenceExecutionControl) !?MetalWorkspaceCensus {
    return snapshotWorkspaceOutsideExecution(session, control, true);
}

pub const QwenWorkspaceCensus = MetalWorkspaceCensus;

fn snapshotWorkspaceOutsideExecution(session: Session, control: ?InferenceExecutionControl, require_existing_roots: bool) !?MetalWorkspaceCensus {
    if (comptime !build_options.enable_metal) return null;
    if (control) |active| try active.check();
    if (!acceptsMetalWorkspaceSession(session)) return null;
    var retained = (try @import("../backends/cold_compute_target.zig").Retained.acquire(session, control)) orelse return null;
    var target_owned = true;
    defer if (target_owned) retained.deinit();
    const target = switch (retained.target) {
        .metal => |value| value,
        else => return null,
    };
    var ticket = try target.exclusion.prepare();
    defer ticket.release() catch platform.inference_process_supervisor.restartWorker();
    const roles = @import("../backends/metal_workspace_roles.zig");
    // Lexical scopes guarantee metadata destructors run AFTER Gate release,
    // including every capture/capacity/identity failure, without bool inference.
    const actual_capacity = blk: {
        try ticket.begin();
        defer ticket.end() catch platform.inference_process_supervisor.restartWorker();
        const provider_owner: *ArchSession = @ptrCast(@alignCast(session.compute_backend_provider.?.ptr));
        if (provider_owner.backend_type != .metal) return null;
        const provider = gpuBackendData(provider_owner).shared_metal_native_provider orelse return null;
        const actual_runtime = provider.raw_decode_runtime orelse return error.WorkspaceTargetChanged;
        if (@as(*anyopaque, @ptrCast(actual_runtime)) != target.runtime or &provider.operations.gate != target.exclusion)
            return error.WorkspaceTargetChanged;
        // Actual metadata exclusion before the no-tag fast decline. The host
        // receiver rechecks absence before math, closing the publication race.
        if (require_existing_roots and provider.workspace_creators.head == null) return null;
        break :blk roles.antfly_metal_workspace_snapshot_capacity(target.runtime);
    };
    if (actual_capacity == 0) return error.WorkspaceCensusUnavailable;
    var physical = try roles.Snapshot.prepare(actual_capacity);
    var physical_owned = true;
    defer if (physical_owned) physical.deinitOutsideExecution();
    if (control) |active| try active.check();
    {
        try ticket.begin();
        defer ticket.end() catch platform.inference_process_supervisor.restartWorker();
        // Snapshot rechecks actual capacity and refuses a raced pool growth;
        // it cannot reallocate or retain any SDK object under exclusion.
        try physical.capture(target.runtime);
    }
    physical_owned = false;
    target_owned = false;
    return .{ .target = retained, .physical = physical };
}

/// First-cold preparation has no selected layer formats yet. Its allocation
/// schedule is exactly the existing greedy scratch/token banks; immutable
/// weights retain the original model/private admission floor. Capturing this
/// separate value never guesses a generic activation or model-weight envelope.
pub const QwenWorkspaceColdAuxiliary = struct {
    census: QwenWorkspaceCensus,
    auxiliary: @import("../backends/metal_workspace_roles.zig").Auxiliary,

    pub fn deinitOutsideExecution(self: *QwenWorkspaceColdAuxiliary) void {
        self.auxiliary.deinitOutsideExecution();
        self.census.deinitOutsideExecution();
        self.* = undefined;
    }
};

pub fn describeQwenWorkspaceAuxiliaryOutsideExecution(session: Session, host_ids_bytes: usize, control: ?InferenceExecutionControl) !?QwenWorkspaceColdAuxiliary {
    if (comptime !build_options.enable_metal) return null;
    var census = (try snapshotQwenWorkspaceOutsideExecution(session, control)) orelse return null;
    var owned = true;
    defer if (owned) census.deinitOutsideExecution();
    const arch: *ArchSession = @ptrCast(@alignCast(session.ptr)); // actual Qwen endpoint already attested
    const cfg = switch (arch.arch_config) {
        .gpt => |value| value,
        else => return null,
    };
    if (!gpt_arch.denseQwen3PrefillEligible(cfg)) return null;
    const roles = @import("../backends/metal_workspace_roles.zig");
    const reserve_kv_tokens = if (cfg.sliding_window > 0) cfg.sliding_window else if (cfg.max_position_embeddings > 0) cfg.max_position_embeddings else 1;
    const greedy = try roles.geometry.greedy(.{
        .hidden = cfg.hidden_size,
        .intermediate = cfg.intermediate_size,
        .heads = cfg.num_attention_heads,
        .kv_heads = cfg.effectiveKVHeads(),
        .head_dim = cfg.headDim(),
        .layers = cfg.num_hidden_layers,
        .vocab = cfg.vocab_size,
        .kv_tokens = reserve_kv_tokens,
    });
    var validation = try roles.Snapshot.prepare(census.physical.entries.len);
    defer validation.deinitOutsideExecution();
    const target = census.target.target.metal;
    var ticket = try target.exclusion.prepare();
    defer ticket.release() catch platform.inference_process_supervisor.restartWorker();
    if (control) |active| try active.check();
    const auxiliary = blk: {
        try ticket.begin();
        defer ticket.end() catch platform.inference_process_supervisor.restartWorker();
        if (MetalCompute.antfly_metal_workspace_policy_available(target.runtime) != 1 or
            MetalCompute.antfly_metal_workspace_decoder_custody_compatible(target.runtime) != 0) return null;
        try validation.capture(target.runtime);
        try census.physical.validate(&validation);
        break :blk try roles.Auxiliary.capture(target.runtime, greedy, host_ids_bytes, .{});
    };
    owned = false;
    return .{ .census = census, .auxiliary = auxiliary };
}

/// Exact owned command declarations + physical identities for one actual
/// pre-admission Qwen frame. It retains no SDK object; its loaded target and
/// pure metadata pins remain synchronous, and are destroyed outside all lanes.
pub const QwenWorkspaceColdPlan = struct {
    census: QwenWorkspaceCensus,
    metadata: MetalCompute.QwenWorkspaceMetadata,
    reference: MetalCompute.WorkspaceReferenceDeclaration,
    tail: MetalCompute.WorkspaceTailDeclaration,
    roles: @import("../backends/metal_workspace_roles.zig").Plan,
    auxiliary: @import("../backends/metal_workspace_roles.zig").Auxiliary,
    pub fn deinitOutsideExecution(self: *QwenWorkspaceColdPlan) void {
        self.tail.deinitOutsideExecution();
        self.roles.deinitOutsideExecution();
        self.auxiliary.deinitOutsideExecution();
        self.metadata.deinitOutsideExecution();
        self.census.deinitOutsideExecution();
        self.* = undefined;
    }
};

/// Same actual selected lowerer, no fake numerical receiver. Published slot
/// formats are copied under short provider exclusion into the existing256-layer
/// registered frame bound; ALL lowerer allocations run after exclusion ends.
/// A second exact slot+census check refuses a raced peer BEFORE admission/math.
pub fn describeQwenWorkspaceOutsideExecution(session: Session, request: *const ops.DecoderRuntimePrefillFramePlanRequest, tail_request: MetalCompute.WorkspaceTailRequest, control: ?InferenceExecutionControl) !?QwenWorkspaceColdPlan {
    if (comptime !build_options.enable_metal) return null;
    if (request.contract != .qwen3_dense_text_prefill or request.include_tail) return null;
    var census = (try snapshotQwenWorkspaceOutsideExecution(session, control)) orelse return null;
    var census_owned = true;
    defer if (census_owned) census.deinitOutsideExecution();
    if (platform.env.getenvBool("TERMITE_METAL_DISABLE_QWEN3_PREPARED_PREFILL")) return null;
    // Tie the request to the ACTUAL factory-owned config, not a forwarded
    // model-contract pointer or caller-supplied dimensions. Full table was
    // accepted by the retained target before this context cast.
    const arch: *ArchSession = @ptrCast(@alignCast(session.ptr));
    const cfg = switch (arch.arch_config) {
        .gpt => |value| value,
        else => return null,
    };
    if (!gpt_arch.denseQwen3PrefillEligible(cfg)) return null;
    const rows = std.math.mul(usize, request.batch, request.seq_len) catch return error.WorkspaceRequestChanged;
    if (request.batch == 0 or request.seq_len == 0 or request.rows != rows or
        request.layer_count != cfg.num_hidden_layers or request.hidden_size != cfg.hidden_size or
        request.vocab_size != cfg.vocab_size or request.num_attention_heads != cfg.num_attention_heads or
        request.global_head_dim != 0 or request.ple_hidden_size != 0 or
        request.final_norm_slot != @import("../backends/decoder_gated_runtime.zig").finalNormSlot(cfg.num_hidden_layers) or
        request.final_lm_head_slot != 0) return error.WorkspaceRequestChanged;
    var expected_layers_storage: [256]ops.DecoderRuntimeLayerSpec = undefined;
    const expected_layers = try @import("../backends/decoder_gated_runtime.zig").fillDenseQwen3LayerSpecs(cfg, cfg.num_hidden_layers, &expected_layers_storage);
    if (request.layers.len != expected_layers.len) return error.WorkspaceRequestChanged;
    for (request.layers, expected_layers) |given, actual| if (!std.meta.eql(given, actual)) return error.WorkspaceRequestChanged;
    const target = census.target.target.metal;
    var ticket = try target.exclusion.prepare();
    defer ticket.release() catch platform.inference_process_supervisor.restartWorker();
    const commands = @import("../graph/metal_command_planner.zig");
    var layer_storage: [256]commands.GatedFrameCommandLowerer.Layer = undefined;
    const layers = blk: {
        try ticket.begin();
        defer ticket.end() catch platform.inference_process_supervisor.restartWorker();
        const provider = try qwenWorkspaceProvider(session);
        if (MetalCompute.antfly_metal_workspace_policy_available(target.runtime) != 1 or
            MetalCompute.antfly_metal_workspace_decoder_custody_compatible(target.runtime) != 0) return null;
        break :blk MetalCompute.copyQwenWorkspaceLayers(provider, request, &layer_storage) orelse return null;
    };
    const metadata = platform.allocator.processAllocator(platform.allocator.concurrentFallback());
    var selected = try MetalCompute.QwenWorkspaceMetadata.prepare(metadata, request, layers);
    var selected_owned = true;
    defer if (selected_owned) selected.deinitOutsideExecution();
    const role_types = @import("../backends/metal_workspace_roles.zig");
    const requirements = try role_types.Requirements.fromSelectedDensePrefill(selected.selected.?.view(), request.rows, request.hidden_size, request.num_attention_heads, request.layers);
    var validation = try role_types.Snapshot.prepare(census.physical.entries.len);
    defer validation.deinitOutsideExecution();
    if (control) |active| try active.check();
    const reserve_kv_tokens = if (cfg.sliding_window > 0) cfg.sliding_window else if (cfg.max_position_embeddings > 0) cfg.max_position_embeddings else 1;
    const greedy = try role_types.geometry.greedy(.{
        .hidden = cfg.hidden_size,
        .intermediate = cfg.intermediate_size,
        .layers = cfg.num_hidden_layers,
        .heads = cfg.num_attention_heads,
        .kv_heads = cfg.effectiveKVHeads(),
        .head_dim = cfg.headDim(),
        .vocab = cfg.vocab_size,
        .kv_tokens = reserve_kv_tokens,
    });
    const ids_bytes = try std.math.mul(usize, request.rows, @sizeOf(u32));
    const captured_plans = blk: {
        try ticket.begin();
        defer ticket.end() catch platform.inference_process_supervisor.restartWorker();
        const provider = try qwenWorkspaceProvider(session);
        // No supplier/heap/SDK allocation in this revalidation region.
        var current_storage: [256]commands.GatedFrameCommandLowerer.Layer = undefined;
        const current = MetalCompute.copyQwenWorkspaceLayers(provider, request, &current_storage) orelse return error.WorkspaceRoleChanged;
        if (layers.len != current.len) return error.WorkspaceRoleChanged;
        for (layers, current) |before, now| if (!std.meta.eql(before, now)) return error.WorkspaceRoleChanged;
        try validation.capture(target.runtime);
        try census.physical.validate(&validation);
        var captured: role_types.Capture = undefined;
        if (role_types.antfly_metal_graph_workspace_capture(target.runtime, &requirements.bytes, &captured, role_types.capacity) != 0)
            return error.WorkspaceRoleCaptureUnavailable;
        var graph_roles = try role_types.Plan.capture(requirements, captured);
        errdefer graph_roles.deinitOutsideExecution();
        // Standalone embedding upload precedes begin_frame in the actual GPT
        // body. Its bank and the SAME family greedy banks are separate roles;
        // neither can borrow graph-slot capacity or credit.
        var auxiliary = try role_types.Auxiliary.capture(target.runtime, greedy, ids_bytes, .{
            .sequence = request.seq_len,
            .heads = cfg.num_attention_heads,
            .kv_heads = cfg.effectiveKVHeads(),
            .head_dim = cfg.headDim(),
        });
        errdefer auxiliary.deinitOutsideExecution();
        var tail = try MetalCompute.WorkspaceTailDeclaration.capture(provider, tail_request);
        errdefer tail.deinitOutsideExecution();
        const reference = try MetalCompute.WorkspaceReferenceDeclaration.capture(provider, request, selected.selected_layers);
        break :blk .{ .graph = graph_roles, .auxiliary = auxiliary, .tail = tail, .reference = reference };
    };
    census_owned = false;
    selected_owned = false;
    return .{ .census = census, .metadata = selected, .roles = captured_plans.graph, .auxiliary = captured_plans.auxiliary, .tail = captured_plans.tail, .reference = captured_plans.reference };
}

/// Starts an explicit pre-serving/benchmark census on an architecture session.
/// Unsupported or non-Metal sessions return false; there is no backend-pointer
/// downcast outside this factory.
pub fn beginMetalWorkloadProfile(session: Session, regime: ops.WorkloadRegime) !bool {
    if (comptime !build_options.enable_metal) return false;
    if (session.vtable != &arch_vtable) return false;
    const arch_session: *ArchSession = @ptrCast(@alignCast(session.ptr));
    if (arch_session.backend_type != .metal) return false;
    const provider = gpuBackendData(arch_session).shared_metal_native_provider orelse
        return error.MetalWorkloadProfileUnavailable;
    try provider.workloadProfileBegin(@fromBackingInt(@intCast(@backingInt(regime))));
    return true;
}

/// Stops capture at a command-buffer boundary, optionally calibrates every
/// eligible first-slice signature, and returns an owned backend-neutral export.
pub fn endMetalWorkloadProfile(
    session: Session,
    allocator: std.mem.Allocator,
    calibrate_first_slice: bool,
) !?MetalWorkloadProfileExport {
    if (comptime !build_options.enable_metal) return null;
    if (session.vtable != &arch_vtable) return null;
    const arch_session: *ArchSession = @ptrCast(@alignCast(session.ptr));
    if (arch_session.backend_type != .metal) return null;
    const provider = gpuBackendData(arch_session).shared_metal_native_provider orelse
        return error.MetalWorkloadProfileUnavailable;
    try provider.workloadProfileEnd();
    var snapshot = try provider.workloadProfileSnapshot();
    var tuning: metal_runtime.MetalWorkloadTuningSummary = .{};
    if (calibrate_first_slice and snapshot.eligibleForSelection()) {
        if (!metal_runtime.metalJitHasPersistentQualificationCache(provider)) {
            return error.MetalJitQualificationCacheUnavailable;
        }
        try metal_runtime.calibrateFirstMetalTuningSlice(allocator, provider.raw_decode_runtime, &snapshot);
        tuning = try metal_runtime.tuneFirstMetalWorkloadSlice(provider, &snapshot);
    }
    return try metal_runtime.workloadProfileExportWithTuningAlloc(allocator, snapshot, tuning, &provider.jit_scope);
}

test "attachIo reaches native compute backend" {
    const allocator = std.testing.allocator;
    var arch_session = ArchSession{
        .allocator = allocator,
        .arch_config = .{ .gpt = .{
            .hidden_size = 4,
            .num_hidden_layers = 1,
            .num_attention_heads = 1,
            .intermediate_size = 8,
            .vocab_size = 16,
        } },
        .backend_type = .native,
        .backend_data = .{ .native = .{
            .allocator = allocator,
            .resident_weights = .{},
            .lazy_weights = .{},
        } },
    };
    const session = Session{
        .ptr = &arch_session,
        .vtable = &arch_vtable,
    };

    attachIo(session, std.testing.io);
    var cb = try makeComputeBackend(&arch_session, allocator, null);
    defer cb.deinit();
    try std.testing.expect(cb.getIo() != null);
}

fn gpuBackendData(self: *ArchSession) *GpuHostedData {
    return switch (self.backend_type) {
        .metal => if (comptime build_options.enable_metal) &self.backend_data.metal else unreachable,
        else => unreachable,
    };
}

const arch_vtable = Session.VTable{
    .executionOwnerStats = &archExecutionOwnerStats,
    .executionCapabilities = &archExecutionCapabilities,
    .hasLayaDecisions = archHasLayaDecisions,
    .runLayaDecisions = archRunLayaDecisions,
    .run = &archRun,
    .runWithControl = &archRunWithControl,
    .eager_host_services = &eager_host_services,
    .runResident = &archRunResident,
    .runResidentTextEmbedding = &archRunResidentTextEmbedding,
    .runResidentTextEmbeddingWithControl = &archRunResidentTextEmbeddingWithControl,
    .runResidentWithControl = &archRunResidentWithControl,
    .inputInfo = &archInputInfo,
    .outputInfo = &archOutputInfo,
    .independentBatchRows = &archIndependentBatchRows,
    .runGeometry = &archRunGeometry,
    .backend = &archBackend,
    .close = &archClose,
};

fn archRunResidentWithControl(
    ptr: *anyopaque,
    inputs: []const Tensor,
    allocator: std.mem.Allocator,
    control: InferenceExecutionControl,
) !?ResidentOutputs {
    const self: *ArchSession = @ptrCast(@alignCast(ptr));
    if (self.task == .classifier or self.task == .extractor) return null;
    if (self.arch_config == .clip or self.arch_config == .clap) return archRunMediaResident(self, inputs, allocator, control);
    if (self.arch_config == .whisper) return archRunIncrementalEncoderResident(self, inputs, allocator, control);
    const cfg = switch (self.arch_config) {
        .bert => |cfg| cfg,
        // Returning null forces the caller through runWithControl. Never
        // advertise a controlled resident fast path by delegating to an
        // implementation that cannot observe the request lifetime.
        else => return null,
    };
    const bert_inputs = try parseBertRunInputs(inputs);
    const cb = try allocator.create(ops.ComputeBackend);
    errdefer allocator.destroy(cb);
    cb.* = try makeComputeBackend(self, allocator, null);
    cb.execution_control = control;
    errdefer cb.deinit();
    const hidden = try bert_arch.forwardCtWithControl(
        cb,
        allocator,
        cfg,
        bert_inputs.input_ids,
        bert_inputs.attention_mask,
        bert_inputs.token_type_ids,
        bert_inputs.batch,
        bert_inputs.seq_len,
        control,
    );
    errdefer cb.free(hidden);
    const outputs = try allocator.alloc(ops.CT, 1);
    errdefer allocator.free(outputs);
    outputs[0] = hidden;
    return .{
        .outputs = outputs,
        .backend = cb,
        .allocator = allocator,
        .backend_owner = cb,
        .deinit_backend_owner = &deinitResidentComputeBackend,
        .backend_owner_cleanup_services = &resident_compute_cleanup_services,
    };
}

/// Actual architecture-owned projected CT entry. Explicit compiled/graph
/// strategies retain their chosen runtime and decline this eager resident seam.
/// Host wrappers remain responsible for their explicit final host outputs.
fn archRunMediaResident(self: *ArchSession, inputs: []const Tensor, allocator: std.mem.Allocator, control: ?InferenceExecutionControl) !?ResidentOutputs {
    if (self.arch_config != .clip and self.arch_config != .clap) return null;
    if (graphRuntimeStrategyEnabled(self.graph_runtime_strategy)) return null;
    if (inputs.len == 0) return error.MissingInputs;
    const first = inputs[0];
    if (first.shape.len == 0 or first.shape[0] <= 0) return error.InvalidInputShape;
    if (self.backend_type != .native and self.backend_type != .metal and self.backend_type != .cuda) return null;
    // These resident frontends intentionally retain the existing GPU policy.
    // Decline immutable unsupported profiles before constructing any backend.
    if (self.backend_type == .native and first.dtype == .f32 and
        (std.mem.eql(u8, first.name, "pixel_values") or std.mem.eql(u8, first.name, "input_features"))) return null;
    const cb = try allocator.create(ops.ComputeBackend);
    var backend_live = false;
    var transferred = false;
    defer if (!transferred) {
        if (backend_live) cb.deinit();
        allocator.destroy(cb);
    };
    cb.* = try makeComputeBackend(self, allocator, null);
    backend_live = true;
    cb.execution_control = control;
    if (control) |active| try active.check();
    const output: ops.CT = switch (self.arch_config) {
        .clip => |cfg| media: {
            if (first.dtype == .f32 and std.mem.eql(u8, first.name, "pixel_values")) {
                const dims = try mediaFloatInput(first, 4);
                if (first.shape[1] != 3 or first.shape[2] != cfg.image_size or first.shape[3] != cfg.image_size) return error.InvalidInputShape;
                break :media (try clip_arch.visionEncoderForwardResident(cb, allocator, cfg, first.asFloat32(), dims[0])) orelse return null;
            }
            if (cb.vtable.takeRows == null) return null;
            const text = try parseBertRunInputs(inputs);
            break :media try clip_arch.textEncoderForwardTensor(cb, allocator, cfg, text.input_ids, text.batch, text.seq_len);
        },
        .clap => |cfg| media: {
            if (first.dtype == .f32 and std.mem.eql(u8, first.name, "input_features")) {
                const dims = try mediaFloatInput(first, 4);
                const longer = if (inputs.len > 1 and inputs[1].dtype == .bool_) inputs[1].data else &.{};
                break :media (try clap_arch.audioEncoderForwardResident(cb, allocator, cfg, first.asFloat32(), dims[0], dims[1], dims[2], dims[3], longer)) orelse return null;
            }
            if (cb.vtable.takeRows == null) return null;
            const text = try parseBertRunInputs(inputs);
            break :media try clap_arch.textEncoderForwardTensor(cb, allocator, cfg, text.input_ids, text.attention_mask, text.token_type_ids, text.batch, text.seq_len);
        },
        else => unreachable,
    };
    errdefer cb.free(output);
    const expected_width = switch (self.arch_config) {
        .clip => |cfg| cfg.projection_dim,
        .clap => |cfg| cfg.projection_dim,
        else => unreachable,
    };
    const shape = try cb.tensorShape(output, allocator);
    defer allocator.free(shape);
    if (try cb.tensorDType(output) != .f32 or shape.len != 2 or shape[0] != first.shape[0] or shape[1] != expected_width) return error.UnexpectedOutputShape;
    if (control) |active| try active.check();
    const outputs = try allocator.alloc(ops.CT, 1);
    outputs[0] = output;
    transferred = true;
    return .{ .outputs = outputs, .backend = cb, .allocator = allocator, .backend_owner = cb, .deinit_backend_owner = deinitResidentComputeBackend, .backend_owner_cleanup_services = &resident_compute_cleanup_services };
}

fn mediaFloatInput(input: Tensor, rank: usize) ![4]usize {
    if (input.dtype != .f32 or input.shape.len != rank or rank > 4 or !input.isAlignedFor(f32)) return error.InvalidInputShape;
    var shape: [4]usize = @splat(1);
    var elements: usize = 1;
    for (input.shape, 0..) |dimension, axis| {
        if (dimension <= 0) return error.InvalidInputShape;
        shape[axis] = std.math.cast(usize, dimension) orelse return error.InvalidInputShape;
        elements = std.math.mul(usize, elements, shape[axis]) catch return error.InvalidInputShape;
    }
    if (input.data.len != (std.math.mul(usize, elements, @sizeOf(f32)) catch return error.InvalidInputShape)) return error.InvalidInputShape;
    return shape;
}

fn archRunIncrementalEncoderResident(self: *ArchSession, inputs: []const Tensor, allocator: std.mem.Allocator, control: ?InferenceExecutionControl) !?ResidentOutputs {
    if (self.arch_config != .whisper or inputs.len != 1) return null;
    const first = inputs[0];
    if (first.dtype != .f32 or !std.mem.eql(u8, first.name, "input_features")) return null;
    const config = self.arch_config.whisper;
    if (first.shape.len != 3 or first.shape[0] <= 0 or first.shape[1] != config.num_mel_bins or first.shape[2] <= 0 or !first.isAlignedFor(f32)) return error.InvalidInputShape;
    const batch = std.math.cast(usize, first.shape[0]) orelse return error.ResourceLimitExceeded;
    const frames = std.math.cast(usize, first.shape[2]) orelse return error.ResourceLimitExceeded;
    const row_elements = std.math.mul(usize, config.num_mel_bins, frames) catch return error.ResourceLimitExceeded;
    const elements = std.math.mul(usize, batch, row_elements) catch return error.ResourceLimitExceeded;
    const bytes = std.math.mul(usize, elements, @sizeOf(f32)) catch return error.ResourceLimitExceeded;
    if (first.data.len != bytes) return error.InvalidInputShape;
    const mel_shape = [_]i32{ std.math.cast(i32, batch) orelse return error.ResourceLimitExceeded, std.math.cast(i32, config.num_mel_bins) orelse return error.ResourceLimitExceeded, std.math.cast(i32, frames) orelse return error.ResourceLimitExceeded };
    const rows = (std.math.add(usize, frames, 1) catch return error.ResourceLimitExceeded) / 2;
    const cb = try allocator.create(ops.ComputeBackend);
    errdefer allocator.destroy(cb);
    cb.* = try makeComputeBackend(self, allocator, null);
    cb.execution_control = control;
    errdefer cb.deinit();
    if (control) |active| try active.check();
    const mel = try cb.fromFloat32Shape(first.asFloat32(), &mel_shape);
    defer cb.free(mel);
    const encoded = try whisper_arch.encoderForwardTensor(cb, allocator, config, mel, batch, frames);
    defer cb.free(encoded);
    const hidden = try cb.primReshape(encoded, &.{ first.shape[0], std.math.cast(i64, rows) orelse return error.ResourceLimitExceeded, config.d_model });
    errdefer cb.free(hidden);
    const outputs = try allocator.alloc(ops.CT, 1);
    outputs[0] = hidden;
    return .{ .outputs = outputs, .backend = cb, .allocator = allocator, .backend_owner = cb, .deinit_backend_owner = deinitResidentComputeBackend, .backend_owner_cleanup_services = &resident_compute_cleanup_services };
}

fn acceptsResidentComputeCleanup(outputs: *const ResidentOutputs) bool {
    return outputs.deinit_backend_owner == deinitResidentComputeBackend;
}
const resident_compute_cleanup_services = ResidentOutputs.BackendOwnerCleanupServices{ .accepts = acceptsResidentComputeCleanup, .deinit = deinitResidentComputeBackendWithCleanup, .detach_dense_f32 = detachResidentDenseF32Payload };
fn detachResidentDenseF32Payload(outputs: *ResidentOutputs, current: @import("cleanup_context.zig").Context) !bool {
    const model = outputs.model_retention orelse return false;
    if (outputs.backend_owner_cleanup_services != &resident_compute_cleanup_services or
        outputs.deinit_backend_owner != deinitResidentComputeBackend or
        outputs.backend_owner != @as(*const anyopaque, @ptrCast(outputs.backend))) return false;
    // Static exact model services must veto wrappers before an owner cast.
    if (model.destroy_fn != archClose or model.quiesce_fn != archQuiesce) return false;
    const owner: *ArchSession = @ptrCast(@alignCast(model.owner));
    if (owner.backend_type != .metal) return false;
    if (comptime !build_options.enable_metal) return false;
    if (&owner.model_lifetime != model) return false;
    // Current B and its exact live numerical operation are both required.
    // Keep supervision through producer completion AND original Engine teardown.
    _ = try current.operationFor(outputs.backend);
    const control = outputs.backend.execution_control orelse return error.ExecutionControlRequired;
    var sdk_guard = try control.enterUninterruptible(.uninterruptible);
    defer sdk_guard.deinit();
    const payload = (try outputs.backend.detachDenseF32PhysicalPayload(outputs.outputs, @ptrCast(gpuBackendData(owner)), current)) orelse return false;
    var replacement = outputs.*;
    replacement.outputs = payload.outputs;
    replacement.backend = payload.backend;
    replacement.allocator = payload.allocator;
    replacement.backend_owner = payload.backend;
    replacement.deinit_backend_owner = deinitResidentComputeBackend;
    replacement.backend_owner_cleanup_services = &resident_compute_cleanup_services;
    replacement.model_retention = model.retain();
    // Exact move of the existing request quota and cold shell; old SDK/header
    // destruction cannot refund the still-live physical payload.
    outputs.resource_lease = null;
    outputs.retirement_shell = null;
    outputs.deinitWithCleanup(current);
    outputs.* = replacement;
    return true;
}

fn deinitResidentComputeBackendWithCleanup(owner: *anyopaque, allocator: std.mem.Allocator, current: @import("../execution/cleanup_context.zig").Context) void {
    const cb: *ops.ComputeBackend = @ptrCast(@alignCast(owner));
    cb.deinitWithCleanup(current);
    allocator.destroy(cb);
}

fn deinitResidentComputeBackend(owner: *anyopaque, allocator: std.mem.Allocator) void {
    const cb: *ops.ComputeBackend = @ptrCast(@alignCast(owner));
    cb.deinit();
    allocator.destroy(cb);
}

const BertRunInputs = struct {
    input_ids: []const i64,
    attention_mask: []const i64,
    token_type_ids: ?[]const i64,
    batch: usize,
    seq_len: usize,
};

fn validateI64Matrix(tensor: Tensor, expected_shape: ?[2]usize) !struct {
    values: []const i64,
    shape: [2]usize,
} {
    if (tensor.dtype != .i64) return error.InvalidInputType;
    if (tensor.shape.len != 2 or tensor.shape[0] <= 0 or tensor.shape[1] <= 0) return error.InvalidInputShape;
    const shape = [2]usize{
        std.math.cast(usize, tensor.shape[0]) orelse return error.InvalidInputShape,
        std.math.cast(usize, tensor.shape[1]) orelse return error.InvalidInputShape,
    };
    if (expected_shape) |expected| {
        if (!std.mem.eql(usize, &shape, &expected)) return error.InvalidInputShape;
    }
    const element_count = std.math.mul(usize, shape[0], shape[1]) catch return error.InvalidInputShape;
    const expected_bytes = std.math.mul(usize, element_count, @sizeOf(i64)) catch return error.InvalidInputShape;
    if (tensor.data.len != expected_bytes or !tensor.isAlignedFor(i64)) return error.InvalidInputShape;
    return .{ .values = tensor.asInt64(), .shape = shape };
}

fn parseBertRunInputs(inputs: []const Tensor) !BertRunInputs {
    if (inputs.len < 2) return error.MissingInputs;
    const ids = try validateI64Matrix(inputs[0], null);
    const mask = try validateI64Matrix(inputs[1], ids.shape);
    const token_type_ids = if (inputs.len > 2)
        (try validateI64Matrix(inputs[2], ids.shape)).values
    else
        null;
    return .{
        .input_ids = ids.values,
        .attention_mask = mask.values,
        .token_type_ids = token_type_ids,
        .batch = ids.shape[0],
        .seq_len = ids.shape[1],
    };
}

fn parseEmbeddingGemma2Inputs(inputs: []const Tensor, cfg: embedding_gemma2_model.Config) !embedding_gemma2_reference.Request {
    var ids: ?[]const i64 = null;
    var embeddings: ?[]const f32 = null;
    var mask: ?[]const i64 = null;
    var shape: ?[2]usize = null;
    for (inputs) |tensor| {
        if (std.mem.eql(u8, tensor.name, "input_ids")) {
            const matrix = try validateI64Matrix(tensor, shape);
            ids = matrix.values;
            shape = matrix.shape;
        } else if (std.mem.eql(u8, tensor.name, "attention_mask")) {
            const matrix = try validateI64Matrix(tensor, shape);
            mask = matrix.values;
            shape = matrix.shape;
        } else if (std.mem.eql(u8, tensor.name, "inputs_embeds")) {
            if (tensor.dtype != .f32 or tensor.shape.len != 3 or tensor.shape[0] <= 0 or tensor.shape[1] <= 0 or tensor.shape[2] != cfg.hidden_size or !tensor.isAlignedFor(f32))
                return error.InvalidInputShape;
            const matrix_shape = [2]usize{ @intCast(tensor.shape[0]), @intCast(tensor.shape[1]) };
            if (shape) |expected| if (!std.mem.eql(usize, &matrix_shape, &expected)) return error.InvalidInputShape;
            const tokens = std.math.mul(usize, matrix_shape[0], matrix_shape[1]) catch return error.InvalidInputShape;
            const count = std.math.mul(usize, tokens, cfg.hidden_size) catch return error.InvalidInputShape;
            const byte_count = std.math.mul(usize, count, @sizeOf(f32)) catch return error.InvalidInputShape;
            if (tensor.data.len != byte_count) return error.InvalidInputShape;
            embeddings = tensor.asFloat32();
            shape = matrix_shape;
        }
    }
    const resolved_shape = shape orelse return error.MissingInputs;
    const attention_mask = mask orelse return error.MissingInputs;
    const input: embedding_gemma2_reference.Input = if (embeddings) |values|
        .{ .input_embeddings = values }
    else if (ids) |values|
        .{ .token_ids = values }
    else
        return error.MissingInputs;
    const request = embedding_gemma2_reference.Request{
        .input = input,
        .attention_mask = attention_mask,
        .batch = resolved_shape[0],
        .sequence = resolved_shape[1],
    };
    try request.validate(cfg);
    return request;
}

fn validateEmbeddingGemma2Output(values: []const f32, batch: usize, dimension: usize) !void {
    if (batch == 0 or dimension == 0) return error.InvalidEmbeddingOutput;
    const expected = std.math.mul(usize, batch, dimension) catch return error.InvalidEmbeddingOutput;
    if (values.len != expected) return error.InvalidEmbeddingOutput;
    for (0..batch) |row| {
        var norm_squared: f32 = 0;
        for (values[row * dimension ..][0..dimension]) |value| {
            if (!std.math.isFinite(value)) return error.InvalidEmbeddingOutput;
            norm_squared += value * value;
        }
        if (!std.math.isFinite(norm_squared) or norm_squared == 0) return error.InvalidEmbeddingOutput;
    }
}

test "EmbeddingGemma2 output validation is batch exact and finite" {
    try validateEmbeddingGemma2Output(&.{ 0.6, 0.8, 0.8, 0.6 }, 2, 2);
    try std.testing.expectError(error.InvalidEmbeddingOutput, validateEmbeddingGemma2Output(&.{ 0.6, 0.8 }, 2, 2));
    try std.testing.expectError(error.InvalidEmbeddingOutput, validateEmbeddingGemma2Output(&.{ 0.6, 0.8, 0, 0 }, 2, 2));
    try std.testing.expectError(error.InvalidEmbeddingOutput, validateEmbeddingGemma2Output(&.{ 0.6, std.math.nan(f32) }, 1, 2));
    try std.testing.expectError(error.InvalidEmbeddingOutput, validateEmbeddingGemma2Output(&.{}, std.math.maxInt(usize), 2));
}

test "BERT session inputs require matching aligned i64 matrices" {
    const allocator = std.testing.allocator;
    const shape = [_]i64{ 1, 2 };
    var ids = try Tensor.initInt64(allocator, "input_ids", &shape, &.{ 7, 8 });
    defer ids.deinit();
    var mask = try Tensor.initInt64(allocator, "attention_mask", &shape, &.{ 1, 1 });
    defer mask.deinit();
    const parsed = try parseBertRunInputs(&.{ ids, mask });
    try std.testing.expectEqual(@as(usize, 1), parsed.batch);
    try std.testing.expectEqual(@as(usize, 2), parsed.seq_len);

    var wrong_type = try Tensor.initFloat32(allocator, "attention_mask", &shape, &.{ 1, 1 });
    defer wrong_type.deinit();
    try std.testing.expectError(error.InvalidInputType, parseBertRunInputs(&.{ ids, wrong_type }));

    const wrong_shape = [_]i64{ 2, 1 };
    var mismatched = try Tensor.initInt64(allocator, "attention_mask", &wrong_shape, &.{ 1, 1 });
    defer mismatched.deinit();
    try std.testing.expectError(error.InvalidInputShape, parseBertRunInputs(&.{ ids, mismatched }));
}

