    try collectMissingRequiredGptWeights(allocator, .{
        .family = .gpt_neo,
        .num_hidden_layers = 1,
        .position_encoding = .absolute,
        .weight_tying = false,
    }, &names, &missing, false);

    try std.testing.expectEqual(@as(usize, 0), missing.items.len);
}

