                }
                fn reserve(raw: *anyopaque, _: memory.AdmissionAmounts) memory.AdmissionResourceError!usize {
                    const self: *@This() = @ptrCast(@alignCast(raw));
                    self.reserve_calls += 1;
                    self.check(.reserve);
