                    }
                    return 1;
                }
                fn retain(raw: *anyopaque, _: usize, _: memory.AdmissionAmounts) memory.AdmissionResourceError!void {
                    const self: *@This() = @ptrCast(@alignCast(raw));
                    self.check(.retain);
                }
                fn release(raw: *anyopaque, _: usize) void {
                    const self: *@This() = @ptrCast(@alignCast(raw));
                    self.check(.release);
