                std.debug.print("CUDA_STAGE_SUPPLIER_FAILURE callback={s} peer_policy_change={any} scheduling={any} error={s}\n", .{ @tagName(probe.failure_callback.?), probe.failure_during_policy, scheduling, @errorName(err) });
