test "Native panel receiver uses actual Model binding when copied wrappers clear or change policy" {
    if (comptime !build_options.enable_native) return error.SkipZigTest;
    const a = std.testing.allocator;
    var actual = ArchSession{ .allocator = a, .arch_config = .{ .embedding_gemma2 = .{} }, .backend_type = .native, .backend_data = .{ .native = .{ .allocator = a, .resident_weights = .empty, .lazy_weights = .empty } } };
    var session = archSessionHandle(&actual);
    try validateNativePanelPreparationReceiver(session); // genuine unbound raw
    const domain = try @import("../runtime/tier/admission_domain.zig").Domain.create();
    defer domain.release();
    actual.model_lifetime.admission_domain = domain.pin();
    defer actual.model_lifetime.admission_domain.?.release();
    try std.testing.expectError(error.MissingNativePanelAdmission, validateNativePanelPreparationReceiver(session));
    session.run_admission = .{ .controller = &domain.controller, .backend_class = .cpu, .limits = .{}, .static_workspace_bytes = 0, .check_live_memory = false };
    session.execution_gate = &actual.model_lifetime.execution_gate;
    try validateNativePanelPreparationReceiver(session);
    var foreign: runtime.tier.memory.AdmissionController = .{};
    defer foreign.deinit();
    var copied = session;
    copied.run_admission.?.controller = &foreign;
    try std.testing.expectError(error.ForeignAdmissionDomain, validateNativePanelPreparationReceiver(copied));
    try std.testing.expectError(error.ForeignAdmissionDomain, copied.runResident(&.{}, a));
    copied = session;
    copied.run_admission = null;
    try std.testing.expectError(error.MissingNativePanelAdmission, validateNativePanelPreparationReceiver(copied));
    try std.testing.expectError(error.MissingNativePanelAdmission, copied.runResident(&.{}, a));
    copied.model_lifetime = null;
    copied.ptr = @ptrFromInt(16);
    try std.testing.expectError(error.MissingNativePanelOwner, validateNativePanelPreparationReceiver(copied));
    try std.testing.expectError(error.MissingNativePanelOwner, copied.runResident(&.{}, a));
    // Default self-contained public entry: no checkpoint/BLAS requirement.
    // The original Native classifier resident callback declines before math;
    // the new Source must preserve null and release its original one lease.
    defer if (actual.model_lifetime.retirement_sink) |*sink| sink.release();
    var scheduler: @import("../runtime/embedding_scheduler.zig").Scheduler = .{};
    session.cohort_scheduler = &scheduler;
    actual.task = .classifier;
    var declined = try session.runResident(&.{}, a);
    defer if (declined) |*output| output.deinit();
    try std.testing.expect(declined == null);
    try std.testing.expect(scheduler.head == null);
    actual.task = .generic;
    const malformed = session.runResident(&.{}, a);
    defer if (malformed) |maybe| {
        if (maybe) |value| {
            var output = value;
            output.deinit();
        }
    } else |_| {};
    try std.testing.expectError(error.MissingInputs, malformed);
    try std.testing.expect(scheduler.head == null);
    try std.testing.expectEqualDeep(runtime.tier.memory.AdmissionAmounts{}, domain.controller.snapshot());
}

test "Native cache source versions bind exact maintained slots refuse live source claim and saturate before ownership move" {
    if (comptime !build_options.enable_native) return error.SkipZigTest;
    const a = std.testing.allocator;
    var actual = ArchSession{ .allocator = a, .arch_config = .{ .embedding_gemma2 = .{} }, .backend_type = .native, .backend_data = .{ .native = .{ .allocator = a, .resident_weights = .empty, .lazy_weights = .empty, .tier_cache = @import("../runtime/tier/cache.zig").SharedCache.init(.{ .host_limit_bytes = 4096 }) } } };
    const data = &actual.backend_data.native;
    defer data.resident_weights.deinit(a);
    @import("../ops/native_compute.zig").initPrefetchQueue(data, a);
    defer @import("../ops/native_compute.zig").deinitPrefetchQueue(data);
    const session = archSessionHandle(&actual);
    var raw = [_]u16{ 0x3f80, 0x4000 };
    const name = "language_model.norm.weight";
    const source = Tensor{ .allocator = a, .name = name, .dtype = .bf16, .shape = &.{2}, .data = std.mem.sliceAsBytes(&raw), .owns_data = false, .owns_shape = false };
    try data.resident_weights.put(a, name, .{ .tensor = source });
    var compute = NativeCompute.init(a, data, null);
    defer compute.deinit();
    compute.cache_embeddinggemma2_bf16_weights = true;
    const cb = compute.computeBackend();
    var owner = try @import("cleanup_owner.zig").Owner.beginOutsideCleanup();
    defer owner.finishAfterUnlock();
    const current = @import("cleanup_context.zig").Context{ .boundary = owner.epoch() };
    try std.testing.expect(try NativeCompute.beginF32MirrorCacheOperation(&cb, data, current));
    try std.testing.expectError(error.NativeResidentWeightInUse, replaceBlasResidentWeight(session, name, .{ .tensor = source, .source_version = 99 }));
    try std.testing.expectEqual(@as(u64, 0), data.resident_weights.get(name).?.source_version);
    NativeCompute.abortWeightCacheOperation(&cb, data);
    try replaceBlasResidentWeight(session, name, .{ .tensor = source, .source_version = 99 });
    try std.testing.expectEqual(@as(u64, 1), data.resident_weights.get(name).?.source_version);
    const saved = data.resident_weights.get(name).?;
    const other = "language_model.unrelated.weight";
    try replaceBlasResidentWeight(session, other, .{ .tensor = source, .source_version = 99 });
    defer a.free(data.resident_weights.getKey(other).?);
    try std.testing.expectEqual(@as(u64, 0), data.resident_weights.get(other).?.source_version);
    try std.testing.expectEqual(saved.source_version, data.resident_weights.get(name).?.source_version);
    data.resident_weights.getPtr(name).?.source_version = std.math.maxInt(u64);
    try std.testing.expectError(error.NativeWeightSourceVersionExhausted, replaceBlasResidentWeight(session, name, .{ .tensor = source }));
    try std.testing.expectEqual(std.math.maxInt(u64), data.resident_weights.get(name).?.source_version);
    try std.testing.expect(data.resident_weights.get(name).?.tensor.data.ptr == source.data.ptr);
}

test "session budget resolver distinguishes nonzero automatic scratch from explicit overrides and sums distinct workspaces" {
    const memory = runtime.tier.memory;
    const byte_unit = memory.bytes_per_mib;
    const first_scratch = 1024 * byte_unit;
    const second_scratch = 2048 * byte_unit;
    const host = 64 * byte_unit;
    var first = memory.ReservedGenerationWorkspace{ .floor = .{ .backend_limit_bytes = first_scratch, .scratch_limit_bytes = first_scratch }, .capacity = .{ .backend_scratch_bytes = first_scratch } };
    defer first.borrowed.deinit();
    var second = memory.ReservedGenerationWorkspace{ .floor = .{ .backend_limit_bytes = second_scratch, .scratch_limit_bytes = second_scratch }, .capacity = .{ .backend_scratch_bytes = second_scratch } };
    defer second.borrowed.deinit();
    const one = Session{ .ptr = &first, .vtable = undefined, .generation_workspace = &first };
    const two = Session{ .ptr = &second, .vtable = undefined, .generation_workspace = &second };
    const sessions = [_]Session{ one, two, one };
    const automatic: memory.Limits = .{ .host_limit_bytes = host, .scratch_limit_bytes = 512 * byte_unit };
    const resolved = try resolveBudgetLimitsForSessions(&sessions, automatic, .{});
    const prepaid = first_scratch + second_scratch;
    const factory_defaults = memory.defaultLimitsForBackendWithProcessLimit(.gpu, 0);
    try std.testing.expect(factory_defaults.scratch_limit_bytes != 0);
    const from_factory = try resolveBudgetLimitsForSessions(&sessions, factory_defaults, .{ .host_limit_bytes = host });
    try std.testing.expectEqual(@max(factory_defaults.scratch_limit_bytes, prepaid + host), from_factory.scratch_limit_bytes);
    try std.testing.expectEqual(@as(usize, prepaid + host), resolved.scratch_limit_bytes);
    try std.testing.expectEqual(@as(usize, prepaid), resolved.backend_limit_bytes);
    try std.testing.expectEqual(@as(usize, prepaid + host), resolved.combined_limit_bytes);
    var controller: memory.AdmissionController = .{};
    defer controller.deinit();
    var resident = try controller.tryAcquire(.gpu, .{}, .{ .backend_scratch_bytes = prepaid }, false);
    defer resident.release();
    var amounts = memory.AdmissionAmounts{ .host_scratch_bytes = host, .backend_scratch_bytes = first_scratch };
    var credit = try first.acquire(&amounts);
    defer credit.release();
    {
        var request = try controller.tryAcquire(.gpu, resolved, amounts, false);
        defer request.release();
        try std.testing.expectEqual(@as(usize, prepaid + host), controller.snapshot().scratchTotalBytes());
    }
    const strict = try resolveBudgetLimitsForSessions(&sessions, automatic, .{ .scratch_limit_bytes = prepaid + host - 1 });
    try std.testing.expectEqual(@as(usize, prepaid + host - 1), strict.scratch_limit_bytes);
    try std.testing.expectError(error.ResourceTemporarilyUnavailable, controller.tryAcquire(.gpu, strict, amounts, false));
    const below_floor = try resolveBudgetLimitsForSessions(&sessions, automatic, .{ .scratch_limit_bytes = 1, .combined_limit_bytes = 2 });
    try std.testing.expectEqual(@as(usize, 1), below_floor.scratch_limit_bytes);
    try std.testing.expectEqual(@as(usize, 2), below_floor.combined_limit_bytes);
    const unbounded = try resolveBudgetLimitsForSessions(&sessions, .{ .scratch_limit_bytes = 512 * byte_unit }, .{});
    try std.testing.expectEqual(@as(usize, 0), unbounded.host_limit_bytes);
    try std.testing.expectEqual(@as(usize, 0), unbounded.combined_limit_bytes);
    try std.testing.expectEqual(@as(usize, 0), unbounded.scratch_limit_bytes);
}

fn nativeWhisperAssignedSourceCase(a: std.mem.Allocator, admitted: bool) !void {
    if (comptime !build_options.enable_native) return error.SkipZigTest;
    var session = try IncrementalFixture.session(a);
    var session_open = true;
    defer if (session_open) session.close();
    // Match LoadedRuntime/CompositeRuntime's real cold publication contract.
    try session.installOwnedExecutionGate(a);
    const domain = if (admitted) try @import("../runtime/tier/admission_domain.zig").Domain.create() else null;
    defer if (domain) |value| value.release();
    if (domain) |value| {
        session.model_lifetime.?.admission_domain = value.pin();
        session.run_admission = .{ .controller = &value.controller, .backend_class = .cpu, .limits = .{ .host_limit_bytes = 128 * 1024 * 1024 }, .static_workspace_bytes = 0, .check_live_memory = false };
    }

    const owner: *ArchSession = @ptrCast(@alignCast(session.ptr));
    // Duplicate the maintained fixture's nonzero layer to exercise a pending
    // FC2 result across an actual layer boundary, not just the final norm.
    const TensorCopy = struct { name: []const u8, tensor: Tensor };
    var copies: [64]TensorCopy = undefined;
    var count: usize = 0;
    var entries = owner.backend_data.native.resident_weights.iterator();
    while (entries.next()) |entry| if (std.mem.startsWith(u8, entry.key_ptr.*, "model.decoder.layers.0.")) {
        copies[count] = .{ .name = entry.key_ptr.*, .tensor = entry.value_ptr.tensor };
        count += 1;
    };
    for (copies[0..count]) |copy| {
        const key = try std.fmt.allocPrint(a, "model.decoder.layers.1.{s}", .{copy.name["model.decoder.layers.0.".len..]});
        errdefer a.free(key);
        var tensor = try Tensor.initFloat32(a, key, copy.tensor.shape, copy.tensor.asFloat32());
        errdefer tensor.deinit();
        try owner.backend_data.native.resident_weights.put(a, key, .{ .tensor = tensor });
    }
    owner.arch_config.whisper.decoder_layers = 2;
    const hidden = [_]f32{ 0.2, 0.4, -0.1, 0.7, 0.5, 0.6, -0.2, 0.3 };
    var decoder = (try whisperNativeDecoder(session, a, null, &hidden, 2)).?;
    var decoder_open = true;
    defer if (decoder_open) decoder.deinit();
    try std.testing.expect(decoder.cache.native_program != null);
    const program = &decoder.cache.native_program.?;
    const frame = program.schedule.frame.?;
    try std.testing.expect(program.schedule.selected.pool.storage_requirement != null);
    try std.testing.expectEqual(program.schedule.selected.pool.plan.allocations.len, program.schedule.selected.pool.storage_requirement_bounds.len);
    const immutable = program.schedule.root.immutable_bindings orelse return error.MissingWhisperSourceBindings;
    for (immutable.entries) |binding| {
        try std.testing.expect(binding.value == .resident);
        const facts = binding.value.resident;
        try std.testing.expect(facts.planes.len == 1 and facts.planes[0].role == .primary and facts.planes[0].descriptor.shape.dtype == .f32 and facts.planes[0].writable == null);
    }
    var gather_routes: usize = 0;
    for (program.schedule.steps) |node| if (program.schedule.descriptors[node].?.operation == .gather) {
        const selected = program.schedule.selected.pool.preparedKernelRoute(node) orelse return error.MissingWhisperGatherRoute;
        try std.testing.expect(@import("assigned_kernel_route.zig").isDirect(selected));
        gather_routes += 1;
    };
    try std.testing.expectEqual(@as(usize, 2), gather_routes);
    try std.testing.expect(frame.native_program_storage_sealed and frame.storage_admission == null);
    try std.testing.expectEqual(@as(usize, 1), frame.scope_backends);
    if (domain) |value| {
        try std.testing.expect(decoder.program_permit != null and decoder.cold_metadata != null);
        try std.testing.expect(value.controller.snapshot().host_kv_bytes > 0);
        try std.testing.expect(value.controller.snapshot().host_scratch_bytes > 0);
        try std.testing.expectEqual(@as(usize, 0), decoder.cache_permit.?.lease.?.amounts.host_scratch_bytes);
        const private_expected = try (try (try decoder.base_permit.?.lease.?.amounts.merge(decoder.cache_permit.?.lease.?.amounts)).merge(try program.schedule.selected.storageRequirement())).merge(decoder.cold_metadata.?.admittedAmounts());
        const expected = if (program.schedule.definition.shared) |shared| try private_expected.merge(shared.admittedAmounts()) else private_expected;
        try std.testing.expectEqualDeep(expected, value.controller.snapshot());
    }
    try std.testing.expect(frame.scope_cleanup.boundary.? == &program.schedule.numerical_epoch.?);
    try std.testing.expectEqual(decoder.receiver_cleanup.?.epoch.record, program.schedule.numerical_epoch.?.record);
    try std.testing.expectEqual(decoder.receiver_cleanup.?.epoch.nonce, program.schedule.numerical_epoch.?.nonce);
    const cfg = decoder.config;
    // This maintained direct API deliberately owns an ordinary eager cache:
    // its entire numerical body is the original semantic implementation.
    var original = try whisper_arch.DecodeCache.init(&decoder.cb.backend, a, cfg, decoder.encoder_hidden, 2);
    var original_open = true;
    defer if (original_open) original.deinit(&decoder.cb.backend);
    try std.testing.expect(original.native_program == null);
    const first = try decoder.step(&.{ 0, 1 });
    defer a.free(first);
    const first_original = try whisper_arch.decoderStepCachedLogits(&decoder.cb.backend, a, cfg, &.{ 0, 1 }, &original);
    defer a.free(first_original);
    try std.testing.expectEqualSlices(f32, first_original, first);
    const held = try a.dupe(f32, first);
    defer a.free(held);
    const generation = frame.host_input_generation;
    const positions = decoder.positions();
    const initialized = try decoder.cb.backend.toFloat32(decoder.cache.layers[0].k_self.?, a);
    defer a.free(initialized);
    try std.testing.expectError(error.InvalidTensorShape, decoder.step(&.{-1}));
    try std.testing.expectError(error.InvalidTensorShape, decoder.step(&.{@intCast(cfg.vocab_size)}));
    try std.testing.expectEqual(positions, decoder.positions());
    try std.testing.expectEqual(generation, frame.host_input_generation);
    try std.testing.expect(!frame.retired);
    // Cold dummy inputs were released before the real numerical scope. This
    // first multi-token prompt deliberately uses the original eager path, so
    // no planned single-token ingress is currently bound.
    try std.testing.expectEqual(@as(usize, 0), frame.bound_host_input_count);
    var invalid_ids = [_]i64{ 0, 1 };
    var current_position = [_]i64{@intCast(positions)};
    var malformed = Tensor{ .allocator = a, .name = "bad.token", .dtype = .i64, .shape = &.{2}, .data = std.mem.asBytes(&invalid_ids), .owns_data = false, .owns_shape = false };
    var valid_position = Tensor{ .allocator = a, .name = "position", .dtype = .i64, .shape = &.{1}, .data = std.mem.asBytes(&current_position), .owns_data = false, .owns_shape = false };
    try std.testing.expectError(error.InvalidHostIngressBinding, frame.rebindNativeProgramHostInputs(&.{ .{ .node_id = program.token_node, .value = &malformed }, .{ .node_id = program.position_node, .value = &valid_position } }));
    try std.testing.expectEqual(generation, frame.host_input_generation);
    try std.testing.expectEqual(@as(usize, 0), frame.bound_host_input_count);
    const after = try decoder.cb.backend.toFloat32(decoder.cache.layers[0].k_self.?, a);
    defer a.free(after);
    try std.testing.expectEqualSlices(f32, initialized[0 .. positions * cfg.d_model], after[0 .. positions * cfg.d_model]);
    for ([_]i64{ 2, 3, 0 }) |token| {
        const expected = try whisper_arch.decoderStepCachedLogits(&decoder.cb.backend, a, cfg, &.{token}, &original);
        defer a.free(expected);
        const actual = allocation_free: {
            const compute: *NativeCompute = @ptrCast(@alignCast(decoder.cb.backend.ptr));
            const original_allocator = compute.allocator;
            var fail_all = std.testing.FailingAllocator.init(a, .{ .fail_index = 0 });
            compute.allocator = fail_all.allocator();
            defer compute.allocator = original_allocator;
            const values = try decoder.step(&.{token});
            errdefer a.free(values);
            try std.testing.expect(!fail_all.has_induced_failure);
            break :allocation_free values;
        };
        defer a.free(actual);
        try std.testing.expectEqualSlices(f32, expected, actual);
        try std.testing.expectEqualSlices(f32, held, first);
        // A real planned step now owns both scalar bindings. Failed metadata
        // validation must preserve their exact bank bytes, CTs and generation,
        // not merely leave a counter looking plausible.
        try std.testing.expectEqual(@as(usize, 2), frame.bound_host_input_count);
        try std.testing.expectEqual(@as(usize, 2), frame.pool.host_input_plans.len);
        const bound_before = frame.host_bound_inputs[0..2].*;
        const bound_generation = frame.host_input_generation;
        var ingress_before: [2][@sizeOf(i64)]u8 = undefined;
        for (frame.pool.host_input_plans, &ingress_before) |input, *snapshot| {
            const bank = frame.storages[input.allocation] orelse return error.MissingWhisperIngressBank;
            const raw = (try decoder.cb.backend.hostFloat32Read(bank.tensor)) orelse return error.MissingWhisperIngressBytes;
            const bytes = std.mem.sliceAsBytes(raw);
            try std.testing.expect(bytes.len >= snapshot.len);
            @memcpy(snapshot, bytes[0..snapshot.len]);
        }
        try std.testing.expectError(error.InvalidHostIngressBinding, frame.rebindNativeProgramHostInputs(&.{ .{ .node_id = program.token_node, .value = &malformed }, .{ .node_id = program.position_node, .value = &valid_position } }));
        try std.testing.expectEqual(bound_generation, frame.host_input_generation);
        try std.testing.expectEqual(@as(usize, 2), frame.bound_host_input_count);
        try std.testing.expect(!frame.retired);
        for (frame.host_bound_inputs[0..2], bound_before) |current, previous| {
            try std.testing.expectEqual(previous.node_id, current.node_id);
            try std.testing.expect(current.value == previous.value);
        }
        for (frame.pool.host_input_plans, &ingress_before) |input, *snapshot| {
            const bank = frame.storages[input.allocation] orelse return error.MissingWhisperIngressBank;
            const raw = (try decoder.cb.backend.hostFloat32Read(bank.tensor)) orelse return error.MissingWhisperIngressBytes;
            try std.testing.expectEqualSlices(u8, snapshot, std.mem.sliceAsBytes(raw)[0..snapshot.len]);
        }
        try std.testing.expectEqual(program.schedule.steps.len, program.schedule.cursor);
    }
    try std.testing.expect(frame.host_input_generation > generation);
    try std.testing.expectEqual(@as(usize, 1), program.schedule.selected.pool.frames.items.len);
    // Real public close releases its Model reference. Both cache source planes
    // and the independent previously published host output remain valid.
    session.close();
    session_open = false;
    const next = try decoder.step(&.{1});
    defer a.free(next);
    const next_expected = try whisper_arch.decoderStepCachedLogits(&decoder.cb.backend, a, cfg, &.{1}, &original);
    defer a.free(next_expected);
    try std.testing.expectEqualSlices(f32, next_expected, next);
    original.deinit(&decoder.cb.backend);
    original_open = false;
    decoder.deinit();
    decoder_open = false;
    try std.testing.expectEqualSlices(f32, held, first);
    if (domain) |value| try std.testing.expectEqualDeep(runtime.tier.memory.AdmissionAmounts{}, value.controller.snapshot());
}

